RSpec.describe "Committed-data lock-wait helpers", committed_data: true do
  # Any fixed key works; no other spec takes this advisory lock.
  def lock_wait_helpers_advisory_key
    155_001
  end

  # Holds the advisory lock on one thread and starts a second thread that
  # waits for it. Yields both server process ids, then releases the lock.
  def with_advisory_lock_waiter
    holder_pids = Queue.new
    waiter_pids = Queue.new
    locked = Queue.new
    release = Queue.new
    holder = committed_data_thread(holder_pids) do
      connection = ActiveRecord::Base.connection
      connection.select_value("SELECT pg_advisory_lock(#{lock_wait_helpers_advisory_key})")
      locked.push(true)
      release.pop
      connection.select_value("SELECT pg_advisory_unlock(#{lock_wait_helpers_advisory_key})")
    end
    holder_pid = holder_pids.pop(timeout: 5)
    locked.pop(timeout: 5)
    waiter = committed_data_thread(waiter_pids) do
      connection = ActiveRecord::Base.connection
      connection.select_value("SELECT pg_advisory_lock(#{lock_wait_helpers_advisory_key})")
      connection.select_value("SELECT pg_advisory_unlock(#{lock_wait_helpers_advisory_key})")
    end
    begin
      yield holder_pid, waiter_pids.pop(timeout: 5)
    ensure
      release.push(true)
      holder.join(5)
      waiter.join(5)
    end
  end

  it "reports the server process id of the connection that runs the block" do
    pids = Queue.new

    pid_in_block = committed_data_thread(pids) { ActiveRecord::Base.connection.select_value("SELECT pg_backend_pid()") }.value

    expect(pids.pop(timeout: 5)).to eq(pid_in_block)
  end

  it "runs the block and returns its value when no pid queue is given" do
    expect(committed_data_thread { :ran }.value).to eq(:ran)
  end

  it "reports a waiter blocked by the session that holds its lock" do
    with_advisory_lock_waiter do |holder_pid, waiter_pid|
      expect(blocked_by?(waiter_pid, holder_pid)).to be(true)
    end
  end

  it "does not report the holder as blocked by its waiter" do
    with_advisory_lock_waiter do |holder_pid, waiter_pid|
      expect(blocked_by?(holder_pid, waiter_pid, within: 0.2)).to be(false)
    end
  end
end

